import kmKhKeyboardCssUrl from './km_KH_keyboard.scss?url';
import { olEditorPluginData } from './km_KH_ol_editor.ts';
import { EditorPreferencesStore } from '../../scripts/app/EditorPreferencesStore.ts';
import type {
  OpenLyricComponentHost,
  OpenLyricContributions,
  OpenLyricPlugin,
  OpenLyricSurface,
} from '../../components/index.ts';

/**
 * km-KH expressed in the generic per-component plugin contract from
 * `research/editor-structure-enhanced.md` — one class per surface, because
 * each surface consumes a different subset:
 *
 * - {@link EditorPluginKmKh}                   — `editor`: fonts + the
 *   Hunspell spellcheck spec + the NiDA on-screen keyboard (mounted live on
 *   a standalone `Editor`, Ctrl+Alt+K via Monaco actions).
 * - {@link OpenLyricMarkdownManagerPluginKmKh} — `markdown`: fonts.
 * - {@link OpenLyricPluginKmKh}                — `lyric`: fonts.
 *
 * All contribution data is the real km_KH plugin data (`km_KH_ol_editor.ts`)
 * — dictionaries, word patterns, provider factory, keyboard spec — not a
 * parallel copy. The spellcheck contribution is declarative today: hosts
 * validate it (reserved `en`, duplicate codes) and the wrapped application
 * still runs the workers; a standalone `Editor` consuming the spec directly
 * is the next migration phase.
 */

/** Khmer-capable faces, led by the app-shipped `editor-Battambang`. */
const KM_KH_FONT_FACES = [
  'editor-Battambang',
  ...olEditorPluginData.pptxStyle.fontFamilyChoices,
];

const KM_KH_FONT_STACK =
  "'editor-Battambang', 'Battambang', 'Kh Battambang', 'Hanuman', sans-serif";

/**
 * Font styling for preview surfaces. The `@font-face` for
 * `editor-Battambang` ships with the app stylesheet (`styles/font.scss`);
 * a bare embed must load those faces itself for the first choice to apply.
 */
const KM_KH_PREVIEW_FONT_STYLE = {
  cssText: `.ol-preview-root { font-family: ${KM_KH_FONT_STACK}; }`,
};

const kmKhLanguageContribution = {
  spellcheck: olEditorPluginData.spellChecker,
  keyboard: {
    id: olEditorPluginData.keyboard.id,
    displayName: olEditorPluginData.keyboard.displayName,
    create: olEditorPluginData.keyboard.create,
  },
  fontFaces: KM_KH_FONT_FACES,
};

interface KhmerKeyboardController {
  close(): void;
  destroy(): void;
  toggle(): void;
}

/** Duck-typed view of `Editor` the keyboard needs (see its docs). */
interface MonacoEditorHostLike {
  monacoEditor?: unknown;
  monacoNamespace?: unknown;
}

/** km-KH for the `editor` surface (`gep`). */
class EditorPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['editor'];
  readonly contributes: OpenLyricContributions = {
    language: kmKhLanguageContribution,
    // NiDA keyboard chrome, active only while the plugin is attached.
    style: { href: kmKhKeyboardCssUrl },
  };

  private keyboardController: KhmerKeyboardController | null = null;
  /** Same store the application uses, so keyboard prefs stay shared. */
  private readonly preferences = new EditorPreferencesStore();

  install(): void {}

  uninstall(): void {
    this.destroyKeyboard();
  }

  onMount(host: OpenLyricComponentHost): void {
    const editorHost = host as unknown as MonacoEditorHostLike;
    const monacoEditor = editorHost.monacoEditor;
    const monaco = editorHost.monacoNamespace;

    // The on-screen keyboard is Monaco-only; the textarea fallback (and any
    // non-Editor host) still gets the font/spellcheck declarations.
    if (!monacoEditor || !monaco) {
      return;
    }

    const ownerDocument = host.container?.ownerDocument ?? document;

    try {
      // Registers its own Ctrl+Alt+K open/close Monaco actions and anchors
      // the keyboard UI to the editor's DOM node inside the host container.
      this.keyboardController = olEditorPluginData.keyboard.create({
        editor: monacoEditor,
        monaco,
        onStateChange: () => {},
        ownerDocument,
        ownerWindow: ownerDocument.defaultView ?? window,
        preferences: this.preferences,
        refs: null,
      });
    } catch (error) {
      console.error('km-KH keyboard failed to mount.', error);
      this.keyboardController = null;
    }
  }

  onUnmount(): void {
    this.destroyKeyboard();
  }

  /** Programmatic access mirroring the Ctrl+Alt+K Monaco actions. */
  toggleKeyboard(): void {
    this.keyboardController?.toggle();
  }

  closeKeyboard(): void {
    this.keyboardController?.close();
  }

  get isKeyboardMounted(): boolean {
    return this.keyboardController !== null;
  }

  private destroyKeyboard(): void {
    try {
      this.keyboardController?.destroy();
    } catch (error) {
      console.error('km-KH keyboard failed to dispose.', error);
    }
    this.keyboardController = null;
  }
}

/** km-KH for the `markdown` surface (`gmp`): Khmer-capable fonts. */
class OpenLyricMarkdownManagerPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['markdown'];
  readonly contributes: OpenLyricContributions = {
    language: { fontFaces: KM_KH_FONT_FACES },
    style: KM_KH_PREVIEW_FONT_STYLE,
  };

  install(): void {}
  uninstall(): void {}
}

/** km-KH for the `lyric` surface (`glpp`): Khmer-capable fonts. */
class OpenLyricPluginKmKh implements OpenLyricPlugin {
  readonly id = 'km-KH';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['lyric'];
  readonly contributes: OpenLyricContributions = {
    language: { fontFaces: KM_KH_FONT_FACES },
    style: KM_KH_PREVIEW_FONT_STYLE,
  };

  install(): void {}
  uninstall(): void {}
}

export {
  EditorPluginKmKh,
  OpenLyricMarkdownManagerPluginKmKh,
  OpenLyricPluginKmKh,
};
